"""New command reference cards. Existing Bash cards are reused by build.py."""


def card(name, purpose, syntax, chapter, forms, url):
    return dict(name=name, purpose=purpose, syntax=syntax, chapter=chapter, volume='cache',
                aliases=[], situations=[], sources=[dict(title='Официальная документация', url=url)],
                flags=[dict(flag=f, action=a, when=w, example=e, result=r) for f,a,w,e,r in forms])


